"""
        Using a threshold to flag when there is over/under-fitting.
        Default: 0.20
    """
def error_analysis(err_train: Any, err_test: Any, threshold: Any = 0.2) -> object {
    if ((err_test - err_train) > threshold) {
        print("WARNING: OVER-fitting");
        return False;
    }
    if (err_train > threshold) {
        print("WARNING: UNDER-fitting");
        return False;
    }
    return True;
}

"""
    Determine empirically good embedding sizes (formula taken from fastai).

    Args:
        n (int): number of classes
        max_size (int, optional): maximum embedding size. Defaults to 100.

    Returns:
        int: embedding size
    """
def get_embedding_size(n: int, max_size: int = 100) -> int {
    if (n > 2) {
        return min(round((1.6 * (n ** 0.56))), max_size);
    } else {
        return 1;
    }
}

